import Bio.Seq

WT_DNA_STR = ''


if __name__ == "__main__":
    WT_DNA = Bio.Seq.Seq(WT_DNA_STR)
    WT_FULL = WT_DNA.translate()
    WT = WT_FULL.rstrip("*").lstrip("M")
    print(WT)
    print(f"Length : {len(WT)}")

    print(f"Saving to fasta file...", end="")
    with open("../data/WT/sadA_wt_trimmed.fasta", "wt") as fh:
        print(f">sadA_wt_trimmed\n{str(WT)}", file=fh)
    print("Done.")

       
